<script setup lang="ts">
import {ref,shallowRef,triggerRef,computed,watch,onMounted,onBeforeUnmount,nextTick} from 'vue';
import ModuleFrame from '../../components/ModuleFrame.vue';import ModuleToolbar from '../../components/ModuleToolbar.vue';import ModuleSection from '../../components/ModuleSection.vue';import ModuleStatus from '../../components/ModuleStatus.vue';
import {playback} from '../../state/audio.ts';
import {LIMITS,defaults,copy,roles,generate,shuffle,validate,uid,keys,keyRange,refFor,relink,recover,newSession,type Project,type Session,type Role,type Paradigm,type Answers,type Asset} from './model.ts';
import {droppedFiles} from './drop.ts';
import {LocalStore} from './storage.ts';import {MediaBank,importFiles,type Prepared} from './media.ts';import {Runner} from './runner.ts';
import {parseProject,projectJSON,readSequence,sequenceRows,resourceRows,workbook,resultsBlob,download,safeMarkup} from './formats.ts';
const props=withDefaults(defineProps<{active?:boolean}>(),{active:true});const emit=defineEmits<{dirty:[boolean];focus:[boolean];references:[]}>();
const project=ref<Project>(defaults()),tab=ref('素材'),error=ref(''),info=ref(''),busy=ref(false),edited=ref(false),checked=ref(false),heard=ref(false),quiet=ref(false),help=ref(false),prefix=ref(''),seed=ref(20260927),projects=ref<Project[]>([]),sessions=ref<Session[]>([]),answers=ref<Answers>({}),stage=ref<'design'|'questionnaire'|'run'>('design');
const store=new LocalStore(),bank=shallowRef<MediaBank|null>(null),runner=shallowRef<Runner|null>(null),revision=ref(0),preview=shallowRef<Prepared|null>(null);const previewAudio=ref<HTMLAudioElement>();let previewUrl:string|null=null;let disposed=false;let monitor:ReturnType<typeof setInterval>|null=null;let lastTick=0,full=false;const runRoot=ref<HTMLElement>();
const phase=computed(()=>{revision.value;return runner.value?.phase??'intro';}),session=computed(()=>{revision.value;return runner.value?{...runner.value.session}:undefined;}),focus=computed(()=>stage.value==='run'&&!!runner.value&&runner.value.focused),dirty=computed(()=>edited.value||!!session.value&&(session.value.exportConfirmedRevision!==session.value.revision));
const current=computed(()=>session.value?.project.trials[session.value.nextIndex]),effective=computed(()=>session.value?keys(session.value.project,session.value.nextIndex):[]),notice=computed(()=>session.value?keyRange(session.value.project,session.value.nextIndex)?.notice:'');
const runtime=computed(()=>session.value?.project??project.value),instruction=computed(()=>current.value?.instruction||(runtime.value.config.showInterTrialText?runtime.value.config.interTrialText:''));
const phaseText:Record<string,string>={intro:'指导语',notice:'阶段提示',interstitial:'试次间隔',ready:'等待手动播放',preparing:'正在准备刺激',playing:'正在播放，请等待',responding:'请作答',saving:'正在提交本地结果',paused:'实验已暂停', 'saving-error':'本地保存失败',completed:'实验结束'};
watch(dirty,v=>emit('dirty',v),{immediate:true});watch(focus,v=>emit('focus',v));
const automaticExports=new Set<string>();watch(phase,p=>{const r=runner.value;if(p==='completed'&&r?.session.status==='completed'&&!automaticExports.has(r.session.id)){automaticExports.add(r.session.id);download(resultsBlob(r.session,'xlsx'),`m15-${r.session.id}.xlsx`);void r.exportRequested().then(changed);info.value='实验结束，XLSX 下载请求已发出。请继续导出完整溯源 JSON 并确认文件保存。';}});
watch(project,()=>{edited.value=true;checked.value=false;heard.value=false;},{deep:true});
watch(()=>props.active,v=>{if(!v&&runner.value?.focused)void runner.value.interrupt('module-hidden');stopPreview();});
function changed(){revision.value++;triggerRef(runner);}
async function action(fn:()=>Promise<void>|void){if(busy.value)return;error.value='';busy.value=true;try{await fn();}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
async function refresh(){projects.value=await store.list<Project>('projects');sessions.value=(await store.list<Session>('sessions')).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));}
async function save(){if(busy.value||runner.value?.focused)return false;try{await store.saveProject(copy(project.value));edited.value=false;await refresh();if(session.value&&session.value.exportConfirmedRevision!==session.value.revision){error.value='请先导出结果并确认文件已保存，再关闭。';return false;}info.value='项目配置已写入本机浏览器存储；请另行导出配置文件。';return true;}catch(e){error.value=String(e);return false;}}
defineExpose({save});
async function loadProject(p:Project){if(edited.value&&!confirm('载入项目会替换当前设计。尚未保存的设计请先导出。继续？'))return;project.value=copy(p);await nextTick();edited.value=false;info.value='配置已恢复；刺激完整性须重新预检。';}
async function filesInput(e:Event,r:Role){const target=e.target as HTMLInputElement,files=Array.from(target.files??[]);await addFiles(files,r);target.value='';}
async function addFiles(files:File[],r:Role){await action(async()=>{const canonical=generate(project.value);const managed=!project.value.trials.length||(canonical.length===project.value.trials.length&&canonical.every((t,i)=>JSON.stringify(t.stimuli)===JSON.stringify(project.value.trials[i].stimuli)));const assets=await importFiles(files,r,project.value.assets,store);let added=0;for(const a of assets){if(!project.value.assets.some(old=>old.hash===a.hash&&old.group===a.group&&old.path===a.path)){project.value.assets.push(a);added++;}}relink(project.value);if(managed&&added)project.value.trials=generate(project.value);checked.value=false;heard.value=false;info.value=`已读取 ${assets.length} 个本地素材，新增 ${added} 项，没有上传。`;});}
async function dropFiles(e:DragEvent,r?:Role){try{if(!e.dataTransfer)return;const files=await droppedFiles(e.dataTransfer);if(r)await addFiles(files,r);else {download(new Blob([workbook(resourceRows(files,project.value.paradigm,prefix.value),'Resource_List')]),'m15-resources.xlsx');info.value='资源模板下载请求已发出。';}}catch(e){error.value=String(e);}}
function changeParadigm(e:Event){const p=(e.target as HTMLSelectElement).value as Paradigm;if(project.value.trials.length&&!confirm('切换范式将按分组重建序列并清除分段/洗牌范围。保留素材及问卷，继续？')){(e.target as HTMLSelectElement).value=project.value.paradigm;return;}project.value.paradigm=p;project.value.config.keyRanges=[];project.value.config.shuffleRanges=[];project.value.trials=generate(project.value);}
function move(i:number,delta:number){const j=i+delta;if(j<0||j>=project.value.trials.length)return;const [t]=project.value.trials.splice(i,1);project.value.trials.splice(j,0,t);}
let dragIndex=-1;function drop(i:number){if(dragIndex<0)return;const [t]=project.value.trials.splice(dragIndex,1);project.value.trials.splice(i,0,t);dragIndex=-1;}
function sort(reverse=false){project.value.trials.sort((a,b)=>(a.stimuli.X?.name??'').localeCompare(b.stimuli.X?.name??'')*(reverse?-1:1));}
function bind(index:number,r:Role,e:Event){const id=(e.target as HTMLSelectElement).value,a=project.value.assets.find(a=>a.id===id);project.value.trials[index].stimuli[r]=a?refFor(a):{id:null,name:project.value.trials[index].stimuli[r]?.name??'',hash:null};}
function stopPreview(){previewAudio.value?.pause();if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=null;preview.value=null;}
function clearGroup(r:Role){if(!confirm(`清空 ${r} 组的项目素材清单？原文件和已保存会话不变。`))return;stopPreview();project.value.assets=project.value.assets.filter(a=>a.group!==r);if(r==='X')project.value.trials=[];}
async function audition(a:Asset){await action(async()=>{stopPreview();bank.value??=new MediaBank(store);await bank.value.unlock();const p=await bank.value.preview(a);checked.value=false;heard.value=false;if(p.buffer)previewUrl=URL.createObjectURL(await store.blob(a.hash));preview.value={...p,url:previewUrl??p.url};});}
async function preflight(){await action(async()=>{stopPreview();const issues=validate(project.value);if(issues.length)throw Error(issues.slice(0,30).join('\n'));if(playback.playing)throw Error('公共播放器正在播放，请先停止试听');if([...document.querySelectorAll('.task-row [role=status]')].some(e=>['运行中','排队中','正在取消'].includes(e.textContent??'')))throw Error('工作台有未结束任务，请先自行处理后再运行实验');bank.value?.dispose();bank.value=new MediaBank(store);await bank.value.unlock();await document.fonts.ready;await document.fonts.load('16px "PTB-Doulos"');await bank.value.preflight(project.value,s=>info.value=s);await bank.value.tone();const cap=await store.capacity();await store.saveProject(copy(project.value));await nextTick();checked.value=true;edited.value=false;info.value=`预检通过，${bank.value.mode==='all'?'全部刺激已解码':'采用试次间分块预加载'}。本机存储约 ${Math.round((cap.usage??0)/1048576)} MiB / ${cap.quota?Math.round(cap.quota/1048576)+' MiB':'容量不可用'}。请确认试音可听见。`;});}
async function importProject(e:Event){const input=e.target as HTMLInputElement,f=input.files?.[0];if(f)await action(async()=>{if(f.size>LIMITS.projectBytes)throw Error('项目配置超过 16 MiB');await loadProject(parseProject(await f.text()));});input.value='';}
async function importSequence(e:Event){const input=e.target as HTMLInputElement,f=input.files?.[0];if(f)await action(async()=>{if(f.size>LIMITS.projectBytes)throw Error('XLSX 超过 16 MiB');project.value.trials=readSequence(await f.arrayBuffer(),project.value);info.value='序列已载入；同名歧义和缺失素材须逐项关联并预检。';});input.value='';}
async function helper(e:Event){const input=e.target as HTMLInputElement;await action(()=>{const files=Array.from(input.files??[]);if(files.length>2000)throw Error('资源助手最多 2000 文件');download(new Blob([workbook(resourceRows(files,project.value.paradigm,prefix.value),'Resource_List')]),'m15-resources.xlsx');info.value='XLSX 下载请求已发出，请检查保存文件。';});input.value='';}
function exportProject(){download(new Blob([projectJSON(project.value)],{type:'application/json'}),'m15-project.json');info.value='配置下载请求已发出。配置不包含素材，请保留原文件。';}
function exportSequence(){download(new Blob([workbook(sequenceRows(project.value,prefix.value))]),'m15-sequence.xlsx');}
async function createRun(){await action(async()=>{if(!checked.value||!heard.value||!quiet.value)throw Error('请完成预检、试音确认及环境确认');if(playback.playing)throw Error('其他音频正在播放');const s=newSession(project.value,answers.value);const r=new Runner(s,bank.value!,store,changed);await r.acquire();try{await store.commit(r.session);}catch(e){await r.dispose();throw e;}runner.value=r;stage.value='run';changed();await nextTick();runRoot.value?.focus();});}
async function resume(id:string){await action(async()=>{const original=await store.session(id);project.value=copy(original.project);answers.value=copy(original.answers);const r=new Runner(recover(original),new MediaBank(store),store,changed);await r.acquire();try{await store.commit(r.session);}catch(e){await r.dispose();r.bank.dispose();throw e;}bank.value?.dispose();bank.value=r.bank;runner.value=r;stage.value='run';r.phase=['completed','ended'].includes(r.session.status)?'completed':'paused';r.message='会话已恢复。可直接导出已有结果；继续前须复核刺激并试音。';await nextTick();checked.value=false;heard.value=false;changed();});}
async function recheckRun(){await action(async()=>{const r=runner.value;if(!r)return;await r.bank.unlock();await r.bank.preflight(r.session.project,s=>info.value=s);await r.bank.tone();checked.value=true;info.value='复核通过，请确认试音后继续。';});}
async function exportResult(format:'json'|'csv'|'xlsx'){const r=runner.value;if(!r)return;await action(async()=>{if(r.focused)await r.interrupt('partial-export','为导出已暂停。重新呈现须明确继续。');download(resultsBlob(r.session,format),`m15-${r.session.id}.${format}`);await r.exportRequested();changed();info.value='下载请求已发出，尚未确认文件已保存。请回读文件后点击确认。';});}
async function back(){if(!runner.value)return;if(dirty.value&&!confirm('结果尚未确认导出。结果保留在本机存储，仍可能被浏览器清理。返回设计？'))return;await runner.value.dispose();runner.value=null;stage.value='design';await refresh();emit('focus',false);}
async function continueRun(){await action(async()=>{const r=runner.value;if(!r)return;if(!checked.value||!heard.value)throw Error('恢复运行前请复核刺激并确认试音');if(r.phase==='paused'&&r.session.attempts.some(a=>a.trialIndex===r.session.nextIndex)&&!confirm('重新呈现当前试次会创建新的 attempt，保留此前中断/异常记录。继续？'))return;await r.bank.unlock();await r.start();await nextTick();runRoot.value?.focus();});}
function down(e:KeyboardEvent){if(!props.active||stage.value!=='run'||!runner.value?.focused)return;e.preventDefault();e.stopImmediatePropagation();runner.value.keydown(e);}
function up(e:KeyboardEvent){runner.value?.keyup(e);}
function interrupted(kind:string){if(stage.value==='run'&&runner.value?.focused)void runner.value.interrupt(kind);}
const freeze=()=>interrupted('page-freeze'),resumeEvent=()=>interrupted('page-resume'),blur=()=>interrupted('window-blur'),visibility=()=>{if(document.hidden)interrupted('document-hidden');},pagehide=()=>interrupted('pagehide'),device=()=>interrupted('devicechange'),fullscreen=()=>{if(full&&!document.fullscreenElement)interrupted('fullscreen-exit');full=!!document.fullscreenElement;};
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue='';}}
watch(bank,b=>{if(b)b.context.onstatechange=()=>{if(b.context.state!=='running')interrupted('audio-context-'+b.context.state);};});
onMounted(async()=>{await action(async()=>{await store.open();await refresh();});window.addEventListener('keydown',down,true);window.addEventListener('keyup',up,true);window.addEventListener('blur',blur);window.addEventListener('pagehide',pagehide);window.addEventListener('beforeunload',beforeUnload);document.addEventListener('visibilitychange',visibility);document.addEventListener('fullscreenchange',fullscreen);document.addEventListener('freeze',freeze);document.addEventListener('resume',resumeEvent);navigator.mediaDevices?.addEventListener('devicechange',device);lastTick=performance.now();monitor=setInterval(()=>{const now=performance.now();if(now-lastTick>2000)interrupted('scheduler-gap');lastTick=now;},500);});
onBeforeUnmount(()=>{disposed=true;stopPreview();void runner.value?.dispose();bank.value?.dispose();if(monitor)clearInterval(monitor);window.removeEventListener('keydown',down,true);window.removeEventListener('keyup',up,true);window.removeEventListener('blur',blur);window.removeEventListener('pagehide',pagehide);window.removeEventListener('beforeunload',beforeUnload);document.removeEventListener('visibilitychange',visibility);document.removeEventListener('fullscreenchange',fullscreen);document.removeEventListener('freeze',freeze);document.removeEventListener('resume',resumeEvent);navigator.mediaDevices?.removeEventListener('devicechange',device);emit('focus',false);});
</script>
<template>
<ModuleFrame label="感知实验工作区" class="perception-page" :aria-busy="busy">
 <template #toolbar><ModuleToolbar><template v-if="stage==='design'"><label>范式 <select aria-label="实验范式" :value="project.paradigm" :disabled="busy" @change="changeParadigm"><option v-for="p in ['X','AX','ABX','AXB']" :key="p">{{p}}</option></select></label><button :disabled="busy" @click="save">保存本机项目{{edited?' *':''}}</button><button :disabled="busy" @click="exportProject">导出项目 JSON</button><label class="file-button">加载项目<input type="file" accept=".json" aria-label="加载项目 JSON" :disabled="busy" @change="importProject"/></label></template><button v-if="stage==='run'" :disabled="busy||phase==='saving'" @click="exportResult('json')">导出已有结果 JSON</button><template #actions><button @click="help=!help">操作说明</button><button @click="emit('references')">方法与来源</button></template></ModuleToolbar></template>
 <template #status><ModuleStatus v-if="error" kind="error" :message="error"/><ModuleStatus v-else-if="info" kind="info" :message="info"/></template>
 <div v-if="help" class="m15-help"><p>数据仅在此设备浏览器保存，无需登录且不上传。先导入素材与序列，预检并试音，再填写问卷运行。配置 JSON 不包含素材，换设备需重新选择原文件，按 SHA-256 关联。</p><p>RT 从作答窗口开放到按键处理计算，音频播放期间不接受答案。文本/图片完成读取和呈现回调后开放。浏览器时钟无法证明耳机发声或物理按键毫秒精度。中断试次保留异常 attempt，重新呈现须明确继续。</p><p>页面和刺激准备完成后可以断网实验。浏览器关闭后的断网重开本轮未提供；Qt 使用内置资源。浏览器存储可能被清理，实验中和结束后均请导出 JSON 与 XLSX/CSV，并确认文件保存。失焦、隐藏、设备/context 事件和长调度间隙会暂停；不能保证检测所有设备故障。</p><p>软件：Vue {{'3.5.42'}}，SheetJS CE 0.20.3（Apache-2.0），Doulos SIL 7（OFL）。旧 React/Babel/Tailwind 不用于本页面。指导语保留加粗、换行等静态 HTML，移除脚本、样式与外链资源。</p></div>
 <template v-if="stage==='design'">
 <div class="m15-tabs" role="tablist" aria-label="实验设计"><button v-for="name in ['素材','序列','参数','问卷','资源与恢复']" :key="name" role="tab" :aria-selected="tab===name" @click="tab=name">{{name}}</button></div>
 <ModuleSection v-if="tab==='素材'" label="素材管理">
 <div class="m15-groups"><section v-for="r in roles(project.paradigm)" :key="r" class="m15-group" @dragover.prevent @drop.prevent="dropFiles($event,r)"><strong>刺激 {{r}}</strong><button :disabled="busy||!project.assets.some(a=>a.group===r)" @click="clearGroup(r)">清空 {{r}} 组</button><label class="file-button">选择或拖入素材<input type="file" multiple accept="audio/*,image/*,.txt,.wav,.flac,.m4a" :aria-label="'导入刺激 '+r" :disabled="busy" @change="filesInput($event,r)"/></label><div v-for="a in project.assets.filter(a=>a.group===r)" :key="a.id" class="m15-asset"><span>{{a.name}}<small>{{a.kind}} · {{a.hash.slice(0,12)}} · {{Math.round(a.size/1024)}} KiB</small></span><button :disabled="busy" :aria-label="'预览 '+a.name" @click="audition(a)">预览</button><button :disabled="busy" @click="project.assets=project.assets.filter(x=>x.id!==a.id)">移除</button></div><p v-if="!project.assets.some(a=>a.group===r)" class="muted">本地音频、图片或 UTF-8 文本；复杂范式仅接受音频。</p></section></div>
 <button @click="stopPreview">停止预览</button><div v-if="preview" class="m15-preview"><audio v-if="preview.buffer&&preview.url" ref="previewAudio" :src="preview.url" controls autoplay @error="error='试听失败，请检查输出设备与文件格式'"/><img v-else-if="preview.url" :src="preview.url" alt="素材预览"/><pre v-if="preview.text" class="ipa-text">{{preview.text}}</pre></div>
 </ModuleSection>
 <ModuleSection v-if="tab==='序列'" label="播放序列">
 <div class="m15-row"><button @click="project.trials=generate(project)">按分组生成序列</button><button @click="sort()">正序 A–Z</button><button @click="sort(true)">倒序 Z–A</button><label>随机种子 <input v-model.number="seed" type="number" min="0" max="4294967295" aria-label="随机种子"/></label><button @click="action(()=>{project=shuffle(project,seed)})">按范围洗牌</button><button @click="action(()=>{project=shuffle(project,seed,[])})">全局洗牌</button></div>
 <div v-for="(r,i) in project.config.shuffleRanges" :key="i" class="m15-row"><label>起始试次<input v-model.number="r.start" type="number"/></label><label>末尾试次<input v-model.number="r.end" type="number"/></label><button @click="project.config.shuffleRanges.splice(i,1)">移除范围</button></div><button @click="project.config.shuffleRanges.push({start:1,end:project.trials.length||1})">添加洗牌范围</button><p class="muted">范围包含首尾，范围外保持不变。重叠范围依列表顺序执行。种子、算法和最终顺序均保存。</p>
 <div class="m15-table"><table><thead><tr><th>顺序</th><th v-for="r in roles(project.paradigm)" :key="r">{{r}} 素材关联</th><th>试次指导语</th><th>操作</th></tr></thead><tbody><tr v-for="(t,i) in project.trials" :key="t.id" draggable="true" @dragstart="dragIndex=i" @dragover.prevent @drop.prevent="drop(i)"><td>{{i+1}}</td><td v-for="r in roles(project.paradigm)" :key="r"><select :aria-label="'试次 '+(i+1)+' '+r" :value="t.stimuli[r]?.id??''" @change="bind(i,r,$event)"><option value="">缺失 / 未关联 {{t.stimuli[r]?.name}}</option><option v-for="a in project.assets" :key="a.id" :value="a.id">{{a.name}} · {{a.hash.slice(0,8)}} [{{a.group}}]</option></select></td><td><input v-model="t.instruction" :aria-label="'试次 '+(i+1)+' 指导语'"/></td><td><button :disabled="i===0" @click="move(i,-1)">↑</button><button :disabled="i===project.trials.length-1" @click="move(i,1)">↓</button><button @click="project.trials.splice(i,1)">移除</button><button @click="project.trials.splice(i+1,0,{...copy(t),id:uid()})">复制</button></td></tr></tbody></table></div><p v-if="!project.trials.length">尚无试次。导入素材后可生成，或通过 XLSX 载入。</p>
 </ModuleSection>
 <ModuleSection v-if="tab==='参数'" label="实验参数">
 <div class="m15-form"><label>实验标题<input v-model="project.config.title" aria-label="实验标题"/></label><label>指导语<textarea v-model="project.config.introText" aria-label="指导语"/></label><label>试次间展示语<textarea v-model="project.config.interTrialText"/></label><label>ISI（ms）<input v-model.number="project.config.isi" type="number" min="0" aria-label="ISI 毫秒"/></label><label>试次间隔（ms）<input v-model.number="project.config.interTrialInterval" type="number" min="0" aria-label="试次间隔毫秒"/></label><label>推进方式<select v-model="project.config.advanceMode" aria-label="推进方式"><option value="auto">自动</option><option value="manual">按键继续</option></select></label></div>
 <div class="m15-row"><label><input v-model="project.config.useBeep" type="checkbox"/>提示音</label><label><input v-model="project.config.autoPlay" type="checkbox"/>自动播放</label><label><input v-model="project.config.showFilename" type="checkbox"/>显示文件名</label><label><input v-model="project.config.showInterTrialText" type="checkbox"/>显示试次间展示语</label><label><input v-model="project.config.introLargeText" type="checkbox"/>指导语大字</label><label><input v-model="project.config.largeText" type="checkbox"/>阶段/试次间大字</label></div>
 <strong>全局按键</strong><div v-for="(k,i) in project.config.validKeys" :key="i" class="m15-row"><input v-model="k.key" maxlength="1" :aria-label="'全局按键 '+(i+1)"/><input v-model="k.label" :aria-label="'按键含义 '+(i+1)"/><button @click="project.config.validKeys.splice(i,1)">移除</button></div><button @click="project.config.validKeys.push({key:'',label:''})">添加按键</button>
 <p class="muted">支持英文字母、数字及空格。重叠分段按列表首项优先，空分段按键回退全局；非法范围阻止开始。</p>
 <section v-for="(r,i) in project.config.keyRanges" :key="r.id" class="m15-group"><div class="m15-row"><label>起始试次<input v-model.number="r.start" type="number"/></label><label>末尾试次<input v-model.number="r.end" type="number"/></label><button @click="project.config.keyRanges.splice(i,1)">移除分段</button></div><label>阶段提示<textarea v-model="r.notice"/></label><div v-for="(k,j) in r.keys" :key="j" class="m15-row"><input v-model="k.key" maxlength="1" aria-label="分段按键"/><input v-model="k.label" aria-label="分段按键含义"/><button @click="r.keys.splice(j,1)">移除</button></div><button @click="r.keys.push({key:'',label:''})">添加分段按键</button></section><button @click="project.config.keyRanges.push({id:uid(),start:1,end:project.trials.length||1,keys:[],notice:''})">添加按键分段</button>
 </ModuleSection>
 <ModuleSection v-if="tab==='问卷'" label="问卷设置"><section v-for="(q,i) in project.questionnaire" :key="q.id" class="m15-group"><div class="m15-row"><label>题目<input v-model="q.label"/></label><label>类型<select v-model="q.type"><option value="text">文本</option><option value="radio">单选</option><option value="checkbox">多选</option></select></label><label><input v-model="q.required" type="checkbox"/>必填</label><button @click="project.questionnaire.splice(i,1)">移除题目</button></div><label v-if="q.type!=='text'">选项（逗号分隔）<input :value="q.options?.join(',')" @input="q.options=($event.target as HTMLInputElement).value.split(/[,，]/).map(x=>x.trim()).filter(Boolean)"/></label></section><button @click="project.questionnaire.push({id:uid(),type:'text',label:'新问题',required:true})">添加问卷题目</button></ModuleSection>
 <ModuleSection v-if="tab==='资源与恢复'" label="资源助手与本地恢复" @dragover.prevent @drop.prevent="dropFiles($event)"><p class="muted">可拖入文件夹生成路径模板，或点击目录选择。最多 2000 文件、16 层目录。</p><div class="m15-row"><label>路径前缀<input v-model="prefix" aria-label="路径前缀"/></label><label class="file-button">目录生成 XLSX 模板<input type="file" webkitdirectory multiple aria-label="资源助手目录" @change="helper"/></label><button @click="exportSequence">导出序列 XLSX</button><label class="file-button">导入序列 XLSX<input type="file" accept=".xlsx" aria-label="导入序列 XLSX" @change="importSequence"/></label><button @click="action(async()=>{info=await store.persist()?'浏览器已授予持久化存储，仍请导出文件':'浏览器未授予持久化，仍可本机保存，请及时导出'})">请求持久化存储</button></div><p>配置和刺激独立检查。相同 hash 可重新关联，同名不同内容须在序列中明确选择。旧 JSON 没有记录复杂范式角色时无法凭空恢复。</p><button @click="action(refresh)">刷新本机记录</button><div v-for="p in projects" :key="p.id" class="m15-row"><span>{{p.config.title}} · {{p.id.slice(0,8)}} · {{p.trials.length}} 试次</span><button @click="action(()=>loadProject(p))">载入项目</button></div><div v-for="s in sessions" :key="s.id" class="m15-row"><span>{{s.createdAt}} · {{s.id.slice(0,8)}} · {{s.nextIndex}}/{{s.project.trials.length}} · {{s.status}}</span><button @click="resume(s.id)">恢复 / 导出会话</button></div></ModuleSection>
 <ModuleSection label="运行预检"><div class="m15-row"><button :disabled="busy" @click="preflight">预检与试音</button><label><input v-model="heard" type="checkbox" :disabled="!checked"/>已听见试音，设备正确</label><label><input v-model="quiet" type="checkbox"/>已暂停其他录制、播放及重型任务</label><button class="primary" :disabled="busy||!checked||!heard||!quiet" @click="stage='questionnaire'">填写被试信息</button></div><p class="muted">预检会播放短提示音，不调整系统音量或默认设备。每次修改配置后重新预检。</p></ModuleSection>
 </template>
 <form v-else-if="stage==='questionnaire'" class="m15-questionnaire" @submit.prevent="createRun"><div v-for="q in project.questionnaire" :key="q.id" class="m15-group"><label v-if="q.type==='text'">{{q.label}}{{q.required?' *':''}}<input v-model="answers[q.id]" :required="q.required" :aria-label="q.label"/></label><fieldset v-else><legend>{{q.label}}{{q.required?' *':''}}</legend><label v-for="opt in q.options" :key="opt"><input v-if="q.type==='radio'" v-model="answers[q.id]" type="radio" :name="q.id" :value="opt" :required="q.required"/><input v-else type="checkbox" :checked="Array.isArray(answers[q.id])&&answers[q.id].includes(opt)" @change="answers[q.id]=($event.target as HTMLInputElement).checked?[...(Array.isArray(answers[q.id])?answers[q.id] as string[]:[]),opt]:(Array.isArray(answers[q.id])?answers[q.id] as string[]:[]).filter(x=>x!==opt)"/>{{opt}}</label></fieldset></div><button type="button" @click="stage='design'">返回设计</button><button class="primary" :disabled="busy">建立独立会话</button></form>
 <section v-else-if="runner&&session" ref="runRoot" class="m15-run" :class="{focused:focus}" tabindex="-1" :data-phase="phase" aria-label="正式实验">
 <div class="m15-runbar"><span>{{runtime.config.title}} · {{Math.min(session.nextIndex+1,runtime.trials.length)}} / {{runtime.trials.length}}</span><span>{{phaseText[phase]}}</span><button v-if="focus" @click="runner.interrupt('manual-pause','手动暂停')">暂停</button><button :disabled="phase==='saving'" @click="exportResult('json')">导出部分 JSON</button><button :disabled="phase==='saving'" @click="runner.end()">结束实验</button></div>
 <div class="m15-presentation">
 <template v-if="phase==='intro'"><div :class="{large:runtime.config.introLargeText}" v-html="safeMarkup(runtime.config.introText)"/><button class="primary" @click="continueRun">开始实验</button></template>
 <template v-else-if="phase==='notice'"><div :class="{large:runtime.config.largeText}" v-html="safeMarkup(notice??'')"/><p>按任意有效的非组合键继续</p><button @click="runner.continue()">继续阶段</button></template>
 <template v-else-if="phase==='interstitial'"><div :class="{large:runtime.config.largeText}" v-html="safeMarkup(instruction)"/><button v-if="runtime.config.advanceMode==='manual'" @click="runner.continue()">进入试次</button></template>
 <button v-else-if="phase==='ready'" class="primary" @click="runner.continue()">播放当前试次</button>
 <template v-else-if="['playing','responding','preparing','saving'].includes(phase)"><p v-if="runtime.config.showFilename">{{current?.stimuli.X?.name}}</p><img v-if="runner.visual?.url" :src="runner.visual.url" alt="实验图片刺激"/><pre v-else-if="runner.visual?.text!==undefined" class="ipa-text">{{runner.visual.text}}</pre><div v-else class="m15-roles"><span v-for="r in roles(runtime.paradigm)" :key="r" :class="{current:runner.activeRole===r}">{{r}}</span></div><p>{{phaseText[phase]}}</p></template>
 <template v-else-if="phase==='paused'||phase==='saving-error'"><ModuleStatus kind="error" :message="runner.message||'已暂停。恢复只在安全边界进行。'"/><p>受影响的试次保留中断/异常记录，继续将创建新的 attempt。</p><button v-if="phase==='saving-error'" @click="runner.retrySave()">重试本地保存</button><button v-else @click="continueRun">明确继续 / 重新呈现</button></template>
 <template v-else-if="phase==='completed'"><p>已保存 {{session.attempts.filter(a=>a.status==='completed').length}} 个有效反应，{{session.attempts.filter(a=>a.status!=='completed').length}} 个异常/中断 attempt。</p><p>请导出文件。浏览器存储不能代替文件备份。</p></template>
 </div>
 <div v-if="['responding','playing','notice'].includes(phase)" class="m15-keys"><span v-for="k in effective" :key="k.key"><kbd>{{k.key===' '?'空格':k.key.toUpperCase()}}</kbd>{{k.label}}</span></div>
 <div v-if="!focus&&phase!=='completed'" class="m15-row"><button @click="recheckRun">复核刺激并试音</button><label><input v-model="heard" type="checkbox" :disabled="!checked"/>已确认恢复试音</label></div>
 <div v-if="!focus" class="m15-row"><button @click="exportResult('json')">完整溯源 JSON</button><button @click="exportResult('xlsx')">兼容 XLSX</button><button @click="exportResult('csv')">兼容 CSV</button><button :disabled="session.exportRequestedRevision===null" @click="action(async()=>{await runner?.confirmExport();changed();info='已记录用户确认保存文件'})">确认导出文件已保存</button><button @click="back">返回设计器</button></div>
 </section>
</ModuleFrame>
</template>
<style scoped>
.perception-page{height:100%;overflow:auto}.m15-row,.m15-tabs{display:flex;gap:var(--control-gap);flex-wrap:wrap;align-items:center;margin:8px 0}.m15-tabs [aria-selected=true]{background:var(--selected);border-color:var(--accent)}.m15-groups,.m15-form{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}.m15-group{border:1px solid var(--border);border-radius:var(--radius);padding:12px;margin:8px 0;background:var(--panel)}.m15-asset{display:flex;align-items:center;gap:8px;margin:8px 0}.m15-asset span{flex:1;min-width:0;overflow-wrap:anywhere}.m15-asset small{display:block;color:var(--muted);font-size:12px}.file-button{display:inline-flex;flex-direction:column;gap:4px;font-size:12px}.file-button input{max-width:220px}.m15-form label,.m15-group>label{display:flex;flex-direction:column;gap:6px}.perception-page input:not([type=checkbox]):not([type=radio]),.perception-page select,.perception-page textarea{background:var(--panel);border:1px solid var(--border);border-radius:5px;color:var(--text);padding:7px;max-width:100%;font:inherit}.m15-row input[type=number]{width:130px}.m15-table{overflow:auto;margin:12px 0}.m15-table table{width:100%;border-collapse:collapse}.m15-table td,.m15-table th{padding:7px;text-align:left;border-bottom:1px solid var(--border)}.m15-table select{max-width:240px}.m15-preview img{max-width:100%;max-height:350px}.m15-help{padding:12px;background:var(--selected);border-radius:8px}.muted{color:var(--muted)}.m15-questionnaire{max-width:700px;margin:auto;width:100%}.m15-questionnaire fieldset label{margin-right:16px}.m15-run{display:flex;flex-direction:column;min-height:560px;background:var(--panel);color:var(--text);outline:none}.m15-run.focused{position:fixed;inset:0;z-index:9000;padding:16px;overflow:auto}.m15-run *{animation:none!important;transition:none!important}.m15-runbar{display:flex;flex-wrap:wrap;align-items:center;gap:12px;font-size:12px}.m15-runbar>span:first-child{flex:1}.m15-presentation{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:24px;padding:32px;min-height:340px}.m15-presentation .large{font-size:calc(var(--control-size,14px)*2);white-space:pre-wrap;max-width:100%;overflow-wrap:anywhere;text-align:center}.m15-presentation img{max-width:80%;max-height:60vh}.m15-presentation pre{font-size:24px;white-space:pre-wrap;overflow:auto;max-height:60vh;max-width:100%}.m15-roles{display:flex;gap:20px}.m15-roles span{display:grid;place-items:center;font-size:40px;width:100px;height:100px;border:2px solid var(--border);border-radius:12px}.m15-roles .current{background:var(--selected);border-color:var(--accent)}.m15-keys{display:flex;justify-content:center;gap:32px;padding:24px;flex-wrap:wrap}.m15-keys span{display:flex;align-items:center;gap:8px}.m15-keys kbd{font-family:var(--font-code,monospace);font-size:24px;padding:8px;border:1px solid var(--border);border-radius:6px}@container module (max-width:720px){.m15-groups,.m15-form{grid-template-columns:1fr}.m15-presentation{padding:16px}.m15-roles span{width:70px;height:70px}}
</style>
